class Task:
    def run_pure(self,inputs,params):
        alias={}
        def bind():
            nonlocal alias
            alias=inputs
            return
            alias={}
        bind()
        alias.pop('seed',None)
        return {}

class Task:
    def run_pure(self,inputs,params):
        alias={}
        def bind():
            nonlocal alias
            alias=inputs
            raise KeyError('seed')
            alias={}
        try:
            bind()
        except KeyError:
            alias.pop('seed',None)
        return {}

class Task:
    def run_pure(self,inputs,params):
        alias={}
        def fallible():
            return params['flag']
        def bind():
            nonlocal alias
            alias=inputs
            fallible()
            alias={}
        try:
            bind()
        except KeyError:
            alias.pop('seed',None)
        return {}
